import { Box } from '@mui/material';
import React from 'react';
import ProjectItem from './ProjectItem';
import SoundCloudItem from './SoundCloudItem';
import SpotifyItem from './SpotifyItem';

export type MusicType = 'soundcloud' | 'spotify';
type ProjectType = 'project';
type ItemType = MusicType | ProjectType;

export type Item__Props = {
  title: string;
  snippet: string;
  readTime?: number | null;
  id: string;
  category: string;
  date: string;
  image?: {
    url: string | null;
  };
  tags: string[];
  embedLink: string | null;
  shareLink?: string;
  skillIds: number[];
  detailLink: string;
  type: ItemType;
  onCopyLink?: (link: string) => Promise<void>;
};

export type ItemMap__Props = {
  data: Item__Props;
};

const ItemMap = (props: ItemMap__Props) => {
  return (
    <Box>
      {
        {
          soundcloud: <SoundCloudItem {...props.data} />,
          project: <ProjectItem {...props.data} />,
          spotify: <SpotifyItem {...props.data} />,
        }[props.data.type]
      }
    </Box>
  );
};

export default ItemMap;
