import React, { useState } from 'react';
import SingleSkill from './SingleSkill';
import { Droppable, Draggable } from 'react-beautiful-dnd';
import AddScrum from './AddScrum';
import { Box, Typography } from '@mui/material';
import { SkillBoardItem } from './Scrumboard';

declare interface SingleBoard__Props {
  skill_title: string;
  update_skill: any;
  board_num?: number;
  addSkill: any;
  list: SkillBoardItem[];
}
const SingleBoard = ({
  skill_title,
  list,
  update_skill,
  board_num,
  addSkill,
}: SingleBoard__Props) => {
  return (
    <Droppable droppableId={skill_title.toLowerCase().replace(/ /gi, '')}>
      {(provided, snapshot) => (
        <div
          className={`skill-scrum--board ${
            snapshot.isDraggingOver ? 'opaque' : ''
          }`}
          ref={provided.innerRef}
          {...provided.droppableProps}
        >
          <div className="skill-scrum--header">
            <Box
              sx={{
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center',
                height: '100%',
              }}
            >
              <Typography
                style={{ color: 'white', fontSize: '1.5rem', fontWeight: 600 }}
                variant="body1"
              >
                {skill_title}
              </Typography>
            </Box>
          </div>

          {list &&
            list.map((sk, index) => (
              <SingleSkill
                key={`${skill_title}--${sk.attributes.slug}-${sk.id}`}
                data={sk}
                update_skill={update_skill}
                index={index}
              />
            ))}

          {provided.placeholder}
          <AddScrum board={skill_title} callback={addSkill} />
        </div>
      )}
    </Droppable>
  );
};

export default SingleBoard;
